import java.util.*;
import java.math.*;
public class BehaviorCheck {
  public static void main(String[] args) throws Exception {
    var items=List.of(new Ranking.Item("z",null),new Ranking.Item("b",8),new Ranking.Item("a",8));
    assert Ranking.rank(items).stream().map(Ranking.Item::name).toList().equals(List.of("a","b","z"));
    var mutable=new ArrayList<>(List.of(new Ranking.Item("x",1),new Ranking.Item("y",2)));Ranking.rank(mutable);assert mutable.get(0).name().equals("x");
    System.out.println("BehaviorCheck: PASS");
  }
}

